link.script:
  // Remove duplicate meta tags by name
  const seen = new Set();
  document.querySelectorAll("meta[name]").forEach(meta => {
    const name = meta.getAttribute("name");
    if (seen.has(name)) {
      meta.remove();
    } else {
      seen.add(name);
    }
  });

  // Remove duplicate meta tags by property (Open Graph etc.)
  const seenProps = new Set();
  document.querySelectorAll("meta[property]").forEach(meta => {
    const prop = meta.getAttribute("property");
    if (seenProps.has(prop)) {
      meta.remove();
    } else {
      seenProps.add(prop);
    }
  }/* MENU CORE */
nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  background-color: #fff0f5;
}

nav ul li {
  position: relative;
  margin-right: 20px;
}

nav ul li a {
  text-decoration: none;
  color: #333;
  font-weight: bold;
  padding: 10px 15px;
  display: block;
}

/* DROPDOWN MENU */
.submenu {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  background: #fff;
  box-shadow: 0 4px 8px rgba(0,0,0,0.1);
  z-index: 1000;
  transition: all 0.3s ease;
}

li:hover > .submenu,
li:focus-within > .submenu {
  display: block;
}

.submenu li {
  white-space: nowrap;
}

.submenu li a {
  font-weight: normal;
}

/* MOBILE RESPONSIVENESS */
@media (max-width: 768px) {
  nav ul {
    flex-direction: column;
    display: none;
  }

  nav ul.open {
    display: flex;
  }

  .menu-toggle {
    display: block;
    cursor: pointer;
    padding: 10px 15px;
    background-color: #f7d6e0;
    font-weight: bold;
    text-align: center;
  }

  .submenu {
    position: relative;
    top: 0;
    left: 0;
    box-shadow: none;
  }
}

body.script:
  // Fetch posts from Blogger API and display them
  function fetchBloggerPosts() {
      const apiKey = 'AIzaSyCiiDLVQPcXbml7_agLscwv9GqK9tCdu5A'; // Your API key
      const blogId = '7056291054171208801'; // Your blog ID
      const url = `https://www.googleapis.com/blogger/v3/blogs/${blogId}/posts?key=${apiKey}&maxResults=6`;

      fetch(url)
          .then(response => response.json())
          .then(data => {
              const container = document.getElementById('post-container');
              container.innerHTML = '';

              if (data.items && data.items.length > 0) {
                  data.items.forEach(post => {
                      const excerpt = post.content.replace(/<[^>]+>/g, '').substring(0, 150) + '...';
                      const postHTML = `



${post.title}

${excerpt}
                              Read more
                          
                      `;
                      container.innerHTML += postHTML;
                  });
              } else {
                  container.innerHTML = '
No posts found.';
              }
          })
          .catch(error => {
              console.log('Error fetching posts:', error);
              document.getElementById('post-container').innerText = 'Failed to load posts.';
          });
  }

  // Run fetch after the page loads
  window.onload = fetchBloggerPosts;

  function googleTranslateElementInit() {
    new google.translate.TranslateElement({pageLanguage: 'en', autoDisplay: false}, 'google_translate_element');
  }

  // Detect browser language and trigger translation if different from English
  window.onload = function() {
    var userLang = navigator.language || navigator.userLanguage;
    userLang = userLang.substring(0,2); // get first two chars
    if(userLang !== 'en') {
      var select = document.querySelector('#google_translate_element select');
      if(select) {
        select.value = userLang;
        select.dispatchEvent(new Event('change'));
      }
    }
  }

