  window.addEventListener("scroll", function () {

    const btn = document.querySelector(".back-to-top");

    if (window.scrollY > 300) {

      btn.style.display = "block";

    } else {

      btn.style.display = "none";

    }

  });

  // Toggle menu for mobile

  document.querySelector('.menu-toggle').addEventListener('click', function() {

    document.querySelector('nav ul').classList.toggle('open');

  });

  // Optional: Smooth submenu toggle on click (for touch devices)

  const menuItems = document.querySelectorAll('nav li > a');

  menuItems.forEach(item => {

    item.addEventListener('click', function(e) {

      const next = this.nextElementSibling;

      if (next && next.classList.contains('submenu')) {

        e.preventDefault();

        next.classList.toggle('open');

      }

    });

  });

  // Toggle main nav on small screens

  document.querySelector('.menu-toggle').addEventListener('click', function () {

    document.querySelector('.main-menu ul').classList.toggle('open');

  });

  // Optional: Toggle submenu on click (for mobile)

  const menuLinks = document.querySelectorAll('.main-menu > ul > li > a');

  menuLinks.forEach(link => {

    link.addEventListener('click', function (e) {

      const submenu = this.nextElementSibling;

      if (submenu && submenu.classList.contains('submenu')) {

        e.preventDefault(); // prevent link from firing

        submenu.classList.toggle('open');

      }

    });

  });

footer.script:
fetch("https://breakupandbloom.blogspot.com/feeds/posts/default?alt=json&max-results=5")
  .then(response => response.json())
  .then(data => {
    const posts = data.feed.entry;
    const container = document.getElementById('latest-posts');
    posts.forEach(post => {
      const title = post.title.$t;
      const link = post.link.find(l => l.rel === 'alternate').href;
      const a = document.createElement('a');
      a.href = link;
      a.textContent = title;
      a.target = '_blank';
      container.appendChild(a);
    });
  });
